package br.gov.dere.api; import br.gov.dere.application.access.AccessService; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController {private final AccessService access;public AuthController(AccessService a){access=a;} @PostMapping("/login") public LoginResponse login(@RequestBody LoginRequest r){access.login(r.login(),r.password());var u=access.userByLogin(r.login());return new LoginResponse(u.getId(),u.getDisplayName(),u.isMaster());} public record LoginRequest(String login,String password){} public record LoginResponse(Long userId,String name,boolean master){} }
